    )
    assert err2.messages == ["a", "b"]
    assert err2.field_name == "x"
    assert err2.normalized_messages() == {"x": ["a", "b"]}
    assert err2.data == {"x": 2}
    assert err2.valid_data == {"x": 3}

    err3 = UndefinedParameterError({"x": ["bad"]})
